Suppose a query algorithm $\alg$ has access to \wtO. The final pure and mixed states of the algorithm are,
\begin{align}
    \ket{\psi^{(\wtO)}} &\coloneq A_q \wtO A_{q-1} \dots \wtO A_0 \ket{0}\\
    \rho_{\alg}^{(\wtO)} &\coloneq \EX_{\substack{\labelPerm \sim S_M\\\colorPerm \sim \colorPresSet}}[\rho(\ket{\psi}^{(\wtO)})]\label{eq:mixed_state_gtO_definition}
\end{align}

The construction of $\wtO$ provides us with the following observations.

\begin{observation}\label{obs:min_num_nodes_per_perm}
    Assume that $n\geq 16$. For every $b\in \middleEdge$ and every $\sigma_b: E_b \to E_b$,
    \begin{align*}
        \abs{E_b} \geq \frac{\sqrt{N}}{4}.
    \end{align*} 
\end{observation}
\begin{proof}
    The smallest permutations used are the ones over columns $c\in \{n/2, 3n/2\}$ and some color $\alpha\in \colorSet$. By \cref{lem:colors_per_column},
    \begin{align*}
        \abs{\treeEdges} \geq \colClassSize{c,\alpha} &\geq \floor{\tfrac{2^{n/2}}{3}} \geq \tfrac{\sqrt{N}}{4}.\qedhere
    \end{align*}
\end{proof}

\subsection{Compressed welded trees oracle}\label{sec:compressed_welded_tree}

In the following subsection, we construct the compressed welded trees oracle \cpwt and prove its soundness, bounded growth and fundamental properties. The construction will replace $\labelPerm$ and $\colorPerm$ with their compressed versions.

A label database is the partial injection $L: [M] \rightharpoonup [M]$. As with $\labelPerm$, we use the convention $L(0)=0$ to fix the entrance vertex and do not count it in $\dom(L)$. An edge (also called color) database $C$ is a family of partial injections $C = \{C_{b}\}_{b\in \middleEdge}$ where each $C_{b}:E_b \rightharpoonup E_b$. We denote the cardinality of $C$ by $\abs{C} = \sum_b \abs{C_b}$. We denote their respective registers by $\Lab$ and $\C$. A pair of the label and color databases is denoted using $I=(L,C)$ under the register $\I$.

For $e_1, e_2 \in E_b$, we write $C[e_1\to e_2]$ to denote extending the injection $C_b$ with $e\to f$ and keeping the rest of $C$ the same. As each edge has a unique label $\edgeIndic(e)$, we may omit the subscript $b$. Furthermore, $C_1 \preceq C_2$ denotes that for all $b\in \middleEdge$, $C_{1,b} \preceq C_{2,b}$.

Following the definition of $\wtF$ in \cref{eq:oracle_function_definition}, \cpwt first \emph{unlabels} using $\pCLabelInv$ (compression operator for $\labelPerm^{-1}$), followed by moving between columns using $\pCPerm$ (compression operator for $\colorPerm$ in $F^{\textup{perm}}$) and finally \emph{relabels} using $\pCLabel$ (compression operator for $\labelPerm$). All three operators perform the recording action. The query-input and query-output registers $\X$ and $\Y$ are written as $\ket{l,\alpha}_{\X} \ket{a}_{\Y}$ where $l,a\in [M]$ and $\alpha\in \colorSet$. The operator $\xorOP$ XORs the label of the adjacent structural vertex into $\Y$.

For a fixed partial edge database $C$, a structural index $v\in [0,M]$ and a color $\alpha\in \colorSet$, let $e = \edgeVertex{\alpha}{v}$ and $b=\edgeIndic(e)$. The partial neighbor map is defined as,
\begin{align}
    \ncF_C(v,\alpha) &\coloneq \begin{cases}
        v &\text{if $v\notin V_n$ or $e=\bot$,}\\
        \head(e) &\text{if $b=\bot$ and $v=\tail(e)$,}\\
        \tail(e) &\text{if $b=\bot$ and $v=\head(e)$,}\\
        \head(C_b(e)) &\text{if $b\in \middleEdge$, $v=\tail(e)$ and $e\in \dom(C_b)$,}\\
        \tail(C_b^{-1}(e)) &\text{if $b\in \middleEdge$, $v=\head(e)$ and $e\in \im(C_b)$,}\\
        \bot &\text{otherwise.}
    \end{cases}
\end{align}
Thus the map $\ncF_C$ uses $C_b$ exactly as $\ncF_{\colorPerm}$ uses $\sigma_b$ in \cref{eq:def_ncf_perm}. Furthermore, notice that when $\ncF_C(v,\alpha)\neq \bot$, we have that $\ncF_C(\ncF_C(v,\alpha),\alpha) = v$.

Let us define the inverse-label compression operator \pCLabelInv, which is essentially just an inverse call to the $\pC$ operator defined in \cref{eq:pc_def}. Letting $l\in [M]$ and $L$ being some label database such that $l\notin \im(L)$,
\begin{align}
    \ket{+_{l,L}^{\mathrm{inv}}} &\coloneq \frac{1}{\sqrt{M - \abs{L}}} \sum_{v\in [M]\setminus \dom(L)} \ket{L[v \to l]}\label{eq:plus_state_label_inv} \\
    \pC^{\mathrm{inv}}_{l,L} &\coloneq \pCfromPlus(\ket{+_{l,L}^{\mathrm{inv}}}, \ket{L})\nonumber\\ 
    \pC^{\mathrm{inv}}_{l} &\coloneq \bigoplus_{L: l\notin \im(L)} \pC^{\mathrm{inv}}_{l,L}\nonumber\\
    \pCLabelInv \ket{l,\alpha}_{\X}\ket{L}_{\Lab} &\coloneq \begin{cases}
        \ket{l,\alpha}_{\X}\left( \pC^{\mathrm{inv}}_{l, \Lab} \ket{L}_{\Lab} \right) &\text{if $l\in [M]$,}\\
        \ket{0,\alpha}_{\X} \ket{L}_{\Lab} &\text{if $l=0$.}
    \end{cases}.\nonumber
\end{align}

Next, we define the compressed edge-permutation operator. Fix $b\in \middleEdge$ and $e\in E_b$. For an edge database $C$, we define the following,
\begin{align}
    \ket{+_{e,b,C}^{\rightarrow}} &\coloneq \frac{1}{\sqrt{\abs{E_b} - \abs{C_b}}} \sum_{e^\prime \in E_b \setminus \im(C_b)} \ket{C[e \to e^\prime]}\label{eq:plus_state_upcolor}\\
    \pC^{\rightarrow}_{e,b} &\coloneq \bigoplus_{C: e\notin \dom(C_b)} \pCfromPlus \left(\ket{+_{e,b,C}^{\rightarrow}}, \ket{C} \right)\label{eq:pC_right_direction}\\
    \ket{+_{e,b,C}^{\leftarrow}} &\coloneq \frac{1}{\sqrt{\abs{E_b} - \abs{C_b}}} \sum_{e^\prime \in E_b \setminus \dom(C_b)} \ket{C[e^\prime \to e]}\label{eq:plus_state_downcolor}\\
    \pC^{\leftarrow}_{e,b} &\coloneq \bigoplus_{C: e\notin \im(C_b)} \pCfromPlus \left(\ket{+_{e,b,C}^{\leftarrow}}, \ket{C} \right)\label{eq:pC_left_direction}
\end{align}
For $v\in V_n$ and $\alpha \in \colorSet$, let $e=\edgeVertex{\alpha}{v}$ and $b=\edgeIndic(e)$. Define,
\begin{align}
    \pC^\prime_{v,\alpha} &\coloneq \begin{cases}
        \pC^{\rightarrow}_{e,b} &\text{if $e\neq \bot$, $b\in \middleEdge$ and $v=\tail(e)$,}\\
        \pC^{\leftarrow}_{e,b} &\text{if $e\neq \bot$, $b\in \middleEdge$ and $v=\head(e)$,}\\
        \Id &\text{otherwise.}
    \end{cases}
\end{align}
The controlled edge-compression operator is defined as,
\begin{align}
    \pCPerm \ket{l,\alpha}_{\X} \ket{L}_{\Lab} \ket{C}_{\C} &\coloneq \begin{cases}
        \ket{l,\alpha}_{\X}\ket{L}_{\Lab} \left( \pC^\prime_{v,\alpha} \ket{C}_{\C} \right) &\text{if $l\in \im(L)$ and $v=L^{-1}(l)$,}\\
        \ket{l,\alpha}_{\X}\ket{L}_{\Lab} \ket{C}_{\C} &\text{otherwise.}
    \end{cases}
\end{align}

The forward-label compression operator is defined using a partial map $\stepFunct(l,\alpha, L, C)$,
\begin{align}
    \stepFunct(l,\alpha, L, C) &\coloneq \begin{cases}
        \ncF_C(L^{-1}(l), \alpha) &\text{if $l\in \im(L) \cup \{0\}$,}\\
        \bot &\text{if $l\notin \im(L) \cup \{0\}$.}
    \end{cases}\\
    \pC^{\mathrm{for}}_{w} &\coloneq \bigoplus_{L: w\notin \dom(L)} \pC_{w,L}\\
    \pCLabel\ket{l,\alpha}_{\X} \ket{L}_{\Lab} \ket{C}_{\C} &\coloneq \begin{cases}
        \ket{l,\alpha}_{\X} \left( \pC^{\mathrm{for}}_{w}\ket{L}_{\Lab}\right) \ket{C}_{\C} &\text{if $w=\stepFunct(l,\alpha, L, C) \notin \{\bot, L^{-1}(l), 0\}$,}\\
        \ket{l,\alpha}_{\X} \ket{L}_{\Lab} \ket{C}_{\C} &\text{if $w\in \{\bot, L^{-1}(l), 0\}$.}
    \end{cases}
\end{align}

Note that we are using the definition of $\pC_{x,I}$ from \cref{eq:pc_x_I}. Finally, we define the XOR operator $\xorOP$ as,
\begin{align*}
    \xorOP\ket{l,\alpha}_{\X}\ket{a}_{\Y} \ket{L,C}_{\I} \coloneq \begin{cases}
        \ket{l,\alpha}_{\X} \ket{a\oplus L(w)}_{\Y} \ket{L,C}_{\I} &\text{if $w = \stepFunct(l,\alpha, L, C) \in \dom(L) \cup \{0\}$,}\\
        \ket{l,\alpha}_{\X}\ket{a}_{\Y} \ket{L,C}_{\I} &\text{otherwise.}
    \end{cases}
\end{align*}

Therefore, we may define the main oracle we will be working with.

