\section{Moments of random Heisenberg couplings}
\label{sec:momsofRHC}
In this section we compute ensemble averages for the random Heisenberg interaction
\begin{equation}
\label{eq:random_heisenberg_interaction}
    \hat K =\sum_{i<j}c_{ij} \hat h_{ij},\quad\quad \hat h_{ij}\coloneqq \hat X_i\hat X_j+\hat Y_i\hat Y_j+\hat Z_i\hat Z_j.
\end{equation}
The coefficients $c_{ij}$ are Gaussian, with their mean subtracted so that $\tr_\mathcal{P}(\hat K)\propto \sum_{i<j} c_{ij}=0$. We choose their standard deviation $\sigma$ so that $\E[\langle \hat K^2\rangle ]=1$, where $\langle \,\cdot\,\rangle\coloneqq \tr_{\mathcal{P}}(\,\cdot\,)/d_{\mathcal{P}}$. The following lemma gives this standard deviation explicitly.
\subsection{Standard deviation}
\begin{lemma}  \label{lemm:std} The condition $\E[\langle \hat K^2\rangle ]=1$ holds if and only if the standard deviation of the coefficients is
 \begin{align}
 \label{eq:std}
     \sigma^{-2}= \,8N(N-1) \eta (1 - \eta), \qquad
     \eta = \frac{k(2N - k + 2)}{4N(N-1)}.
\end{align}
\end{lemma}
\noindent In the limit $N\gg k$, the expression simplifies to
$\sigma^{-2}\approx 4Nk$. 
\begin{proof}
Let us compute the expected variance $\E[\langle{ \hat K^2\rangle }]$ explicitly and set it equal to $1$. We can write
\begin{equation*}
    \hat K = \sum_{i<j} c_{ij} (2 F_{ij} - \mathbb{I}),
\end{equation*}
where $F_{ij}$ is the swap operator between qubits $i$ and $j$. By the constraint $\sum_{i<j} c_{ij} = 0$, the identity term vanishes, yielding
\begin{equation*}
    \hat K = 2 \sum_{\alpha=1}^{N_p} c_\alpha F_\alpha,
\end{equation*}
where $\alpha$ indexes the $N_p = N(N-1)/2$ distinct pairs of sites. The coefficients $c_\alpha$ are Gaussian random variables subject to the sum constraint, which implies the covariance matrix:
\begin{equation*}
    \E[c_\alpha c_\beta] = \sigma^2\left(\delta_{\alpha \beta} - \frac{1}{N_p}\right).
\end{equation*}
We calculate the expected variance:
\begin{equation*}
    \E \!\left[ \langle \hat K^2\rangle  \right] = 4 \sum_{\alpha, \beta} \E[c_\alpha c_\beta] \langle F_\alpha F_\beta\rangle.
\end{equation*}
Substituting the covariance matrix splits the sum into diagonal and off-diagonal parts:
\begin{equation*}
    1=\E[\langle \hat K^2 \rangle] = 4 \sigma^2\left( \sum_\alpha \langle F_\alpha^2\rangle - \frac{1}{N_p} \sum_{\alpha, \beta} \langle F_\alpha F_\beta\rangle \right).
\end{equation*}
Since transpositions square to identity, the first term sums to $N_p$. The second term involves the square of the sum of all transpositions $\mathcal{C}_2 = \sum_\alpha F_\alpha$.
Since the operator $\mathcal{C}_2$ is permutation invariant, it acts as a scalar within the space $\mathcal{P}$. Using the identity $\mathcal{C}_2 = \mathbf{S}_{\text{tot}}^2 + \frac{N(N-4)}{4}$, this scalar must be $z=S(S+1) +N(N-4)/4$, and hence
\begin{equation*}
    \sigma^{-2} =4\left(N_p- \frac{z^2}{N_p}\right).
\end{equation*}
Using $S=(N-k)/2$ one can simplify this equation to Eq.~\eqref{eq:std}.
\end{proof}

\subsection{Variance of a commutator}
The next result gives the variance of a commutator between two independent random Heisenberg couplings.
\begin{lemma}
\label{lemm:commutav}
    Let $\hat K_0$ and $\hat K_1$ be independent random Heisenberg couplings. Then
    \begin{equation}
    \label{eq:commutator}
        \E\left [\langle[\hat K_0,\hat K_1]^\dagger[\hat K_0,\hat K_1]\rangle\right]=\sigma^4 \,32N(N-1)(N-2)(1-\phi_3),
    \end{equation}
where $\sigma$ is given by Lemma~\ref{lemm:std}, 
 and $\phi_3$ is the normalized character of the 3-cycle in the representation with total spin $S$, given by \cite[Eq. (5.2)]{Ingram1950}
\begin{align}
\label{eq:character}
    \phi_3 &= \frac{(N-3)!}{N!} \left( \frac{M_3}{2} - \frac{3}{2}N(N-1) \right),
   \\
    M_3 &= \sum_{j=1}^2 \left[ (\lambda_j - j)(\lambda_j - j + 1)(2\lambda_j - 2j + 1) + j(j-1)(2j-1) \right],&& \lambda_1=N-k/2, && \lambda_2=k/2. \nonumber
\end{align}

\end{lemma}
\begin{proof}
    Let us write $\mathcal{K} = [\hat K_0, \hat K_1]$, and $\hat K_0=2\sum_{\alpha} c_{\alpha}F_{\alpha}$ and $\hat K_1=2\sum_{\beta} c'_{\beta}F_{\beta}$ as sums over transpositions
$F_{ij}$ (with $\alpha,\beta$ indexing unordered pairs), with independent Gaussian coefficients satisfying
$\E[c'_{\alpha}c'_{\beta}]=\E[c_{\alpha}c_{\beta}]=\sigma^2(\delta_{\alpha\beta}-1/N_p)$ and $\E[c_{\alpha}c'_{\beta}]=0$.
Then
\begin{align}
    \mathcal{K}
    &= [\hat K_0,\hat K_1]
    = \left[2\sum_{\alpha} c_{\alpha}F_{\alpha},\,2\sum_{\beta} c'_{\beta}F_{\beta}\right] 
    = 4\sum_{\alpha,\beta} c_{\alpha}c'_{\beta}[F_{\alpha},F_{\beta}]. \label{eq:def-K-comm}
\end{align}
Only non-disjoint pairs contribute: for transpositions, $[F_{ij},F_{kl}]=0$ unless the pairs share exactly one site. There are $N(N-1)(N-2)$ such ordered choices: choose the repeated site in $N$ ways and the other two sites in $(N-1)(N-2)$ ways. The constraints $i<j$ and $k<l$ then fix the internal order within each pair.
For such shared-site pairs, we have
\begin{align*}
    [F_{ij},F_{jk}]
    &= F_{ij}F_{jk}-F_{jk}F_{ij} 
    = F_{(ijk)}-F_{(ikj)}, 
\end{align*}
so that
\begin{align}
    [F_{ij},F_{jk}]^\dagger [F_{ij},F_{jk}]
    = \bigl(F_{(ikj)}-F_{(ijk)}\bigr)\bigl(F_{(ijk)}-F_{(ikj)}\bigr) \nonumber
    = 2\mathbb{I}-F_{(ijk)}-F_{(ikj)}, 
\end{align}
where $F_{(ijk)}\coloneqq F_{ij}F_{jk}$ denotes the operator representing the 3-cycle $(ijk)$ in $\mathcal{P}$ (and $F_{(ikj)}\coloneqq F_{jk}F_{ij}=F_{(ijk)}^\dagger$).
Taking the trace over $\mathcal{P}$ and using $\tr_{\mathcal{P}}(F_{(ijk)})=\tr_{\mathcal{P}}(F_{(ikj)})=d_{\mathcal{P}}\phi_3$ yields 
\begin{align*}
    \langle[F_{ij},F_{jk}]^\dagger [F_{ij},F_{jk}]\rangle
    = 2(1-\phi_3). 
\end{align*}
We now perform an average over disorder. Since the disorder is Gaussian, we evaluate the fourth moments using Wick's theorem,
\begin{align*}
    \E\!\left[c_{\alpha}c_{\alpha'}c_{\gamma}c_{\gamma'}\right]
    &= \E[c_{\alpha}c_{\alpha'}]\E[c_{\gamma}c_{\gamma'}]
    + \E[c_{\alpha}c_{\gamma}]\E[c_{\alpha'}c_{\gamma'}]
    + \E[c_{\alpha}c_{\gamma'}]\E[c_{\alpha'}c_{\gamma}],
\end{align*}
and similarly for the $c'$'s. Mixed contractions vanish since the two disorder families are independent: $\E[c_{\alpha}c'_{\beta}]=0$.
